def summarize(numbers):
    if not numbers:
        return {"count": 0, "sum": 0, "max": None, "min": None, "mean": None}
    total = sum(numbers)
    return {
        "count": len(numbers),
        "sum": total,
        "max": max(numbers),
        "min": min(numbers),
        "mean": total / len(numbers),
    }
